<script src="https://unpkg.com/three@0.128.0/build/three.min.js"></script>
<script>
(function () {
  var S = { frames: 0, firstY: null, err: null, cube: null, scene: null, renderer: null };
  try {
    var scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0d1117);

    var camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 0, 3.2);

    var renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    scene.add(new THREE.AmbientLight(0xffffff, 0.65));
    var dir = new THREE.DirectionalLight(0xffffff, 0.9);
    dir.position.set(3, 4, 5);
    scene.add(dir);

    var cube = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({ color: 0x4ea1ff, metalness: 0.3, roughness: 0.35 })
    );
    scene.add(cube);

    S.scene = scene; S.renderer = renderer; S.cube = cube;

    var clock = new THREE.Clock();
    (function tick() {
      var t = clock.getElapsedTime();
      cube.rotation.x = t * 0.6;
      cube.rotation.y = t * 0.9;
      renderer.render(scene, camera);
      S.frames++;
      if (S.firstY === null) S.firstY = cube.rotation.y;
      requestAnimationFrame(tick);
    })();

    window.addEventListener('resize', function () {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  } catch (e) {
    S.err = String((e && e.message) || e);
  }

  window.__selfcheck = function () {
    var checks = [];
    function add(name, pass, evidence) {
      checks.push({ name: name, pass: !!pass, evidence: String(evidence) });
    }
    var three = (typeof THREE !== 'undefined');
    add('three.js loaded from CDN', three, three ? 'THREE.REVISION=' + THREE.REVISION : 'THREE is undefined');

    var canvas = document.querySelector('canvas');
    add('canvas attached to DOM', !!canvas, canvas ? canvas.width + 'x' + canvas.height : 'no canvas');

    add('cube mesh in scene', !!(S.cube && S.cube.isMesh),
        S.cube ? 'geometry=' + S.cube.geometry.type + ' material=' + S.cube.material.type : 'no mesh');

    add('animation frames advancing', S.frames > 1, 'frames=' + S.frames);

    var nowY = S.cube ? S.cube.rotation.y : 0;
    var delta = (S.firstY === null) ? 0 : nowY - S.firstY;
    add('cube auto-rotating', delta > 1e-3,
        'rotation.y delta=' + delta.toFixed(4) + ' over ' + S.frames + ' frames');

    var info = S.renderer && S.renderer.info && S.renderer.info.render;
    add('renderer produced frames', !!(info && info.frame > 0),
        info ? 'frame=' + info.frame + ' triangles=' + info.triangles : 'not rendered');

    add('no startup error', !S.err, S.err || 'ok');

    return { checks: checks, pass: checks.every(function (c) { return c.pass; }) };
  };

  setTimeout(function () {
    var r = window.__selfcheck();
    var b64 = '';
    try { b64 = btoa(JSON.stringify(r)); } catch (e) { b64 = ''; }
    document.getElementById('selfcheck-out').textContent = 'SCJSON' + b64 + 'ENDSCJSON';
  }, 1200);
})();
</script>
</body>
</html>
